// File: rtl/axis_joiner.sv
`timescale 1ns / 1ps

module axis_joiner (
    // Clock and Reset
    input  wire                   clk,
    input  wire                   rst,

    // Input Stream 1
    input  wire [7:0]             s_axis_tdata_1,
    input  wire                   s_axis_tvalid_1,
    output wire                   s_axis_tready_1,
    input  wire                   s_axis_tlast_1,

    // Input Stream 2
    input  wire [7:0]             s_axis_tdata_2,
    input  wire                   s_axis_tvalid_2,
    output wire                   s_axis_tready_2,
    input  wire                   s_axis_tlast_2,

    // Input Stream 3
    input  wire [7:0]             s_axis_tdata_3,
    input  wire                   s_axis_tvalid_3,
    output wire                   s_axis_tready_3,
    input  wire                   s_axis_tlast_3,

    // Merged Output Stream
    output wire [7:0]             m_axis_tdata,
    output wire                   m_axis_tvalid,
    input  wire                   m_axis_tready,
    output wire                   m_axis_tlast,
    output wire [1:0]             m_axis_tuser,

    // Status
    output wire                   busy
);

    // FSM State Definitions
    typedef enum logic [1:0] {
        STATE_IDLE = 2'b00,
        STATE_1    = 2'b01,
        STATE_2    = 2'b10,
        STATE_3    = 2'b11
    } state_t;

    state_t curr_state, next_state;

    // Internal MUX outputs (combinational)
    logic [7:0] mux_tdata;
    logic mux_tvalid;
    logic mux_tlast;
    logic [1:0] mux_tuser;

    // Stalling/Buffering flag
    logic temp;

    // -----------------------------------------------------------------------
    // Finite State Machine: Next State Logic
    // -----------------------------------------------------------------------
    always_comb begin
        case (curr_state)
            STATE_IDLE: begin
                if (s_axis_tvalid_1) next_state = STATE_1;
                else if (s_axis_tvalid_2) next_state = STATE_2;
                else if (s_axis_tvalid_3) next_state = STATE_3;
                else next_state = STATE_IDLE;
            end
            STATE_1: begin
                if (s_axis_tready_1 && s_axis_tlast_1) next_state = STATE_IDLE;
                else next_state = STATE_1;
            end
            STATE_2: begin
                if (s_axis_tready_2 && s_axis_tlast_2) next_state = STATE_IDLE;
                else next_state = STATE_2;
            end
            STATE_3: begin
                if (s_axis_tready_3 && s_axis_tlast_3) next_state = STATE_IDLE;
                else next_state = STATE_3;
            end
            default: next_state = STATE_IDLE;
        endcase
    end

    // -----------------------------------------------------------------------
    // FSM State Register
    // -----------------------------------------------------------------------
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            curr_state <= STATE_IDLE;
        end else begin
            curr_state <= next_state;
        end
    end

    // -----------------------------------------------------------------------
    // Backpressure Handling & Output Register Update
    // Retains data when m_axis_tready is deasserted using 'temp' flag
    // -----------------------------------------------------------------------
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            m_axis_tdata  <= 8'b0;
            m_axis_tvalid <= 1'b0;
            m_axis_tlast  <= 1'b0;
            m_axis_tuser  <= 2'b0;
            temp          <= 1'b0;
        end else begin
            if (temp) begin
                // Stalled: hold previous outputs until ready signal is asserted
                // temp remains 1
            end else if (m_axis_tready) begin
                // Ready: update outputs and clear stall flag
                m_axis_tdata  <= mux_tdata;
                m_axis_tvalid <= mux_tvalid;
                m_axis_tlast  <= mux_tlast;
                m_axis_tuser  <= mux_tuser;
                temp          <= 1'b0;
            end else begin
                // Not ready: attempt update, set stall flag for next cycle
                if (mux_tvalid) begin
                    m_axis_tdata  <= mux_tdata;
                    m_axis_tvalid <= mux_tvalid;
                    m_axis_tlast  <= mux_tlast;
                    m_axis_tuser  <= mux_tuser;
                    temp          <= 1'b1;
                end else begin
                    m_axis_tvalid <= 1'b0;
                    temp          <= 1'b0;
                end
            end
        end
    end

    // -----------------------------------------------------------------------
    // Multiplexer Assignments (Data, Valid, Last, User)
    // -----------------------------------------------------------------------
    assign mux_tdata = (curr_state == STATE_1) ? s_axis_tdata_1 :
                       (curr_state == STATE_2) ? s_axis_tdata_2 :
                       (curr_state == STATE_3) ? s_axis_tdata_3 : 8'b0;

    assign mux_tvalid = (curr_state == STATE_1) ? s_axis_tvalid_1 :
                        (curr_state == STATE_2) ? s_axis_tvalid_2 :
                        (curr_state == STATE_3) ? s_axis_tvalid_3 : 1'b0;

    assign mux_tlast = (curr_state == STATE_1) ? s_axis_tlast_1 :
                       (curr_state == STATE_2) ? s_axis_tlast_2 :
                       (curr_state == STATE_3) ? s_axis_tlast_3 : 1'b0;

    assign mux_tuser = (curr_state == STATE_1) ? 2'h1 :
                       (curr_state == STATE_2) ? 2'h2 :
                       (curr_state == STATE_3) ? 2'h3 : 2'h0;

    // -----------------------------------------------------------------------
    // Input Ready Signals (Backpressure to sources)
    // -----------------------------------------------------------------------
    assign s_axis_tready_1 = (curr_state == STATE_1) ? 1'b1 : 1'b0;
    assign s_axis_tready_2 = (curr_state == STATE_2) ? 1'b1 : 1'b0;
    assign s_axis_tready_3 = (curr_state == STATE_3) ? 1'b1 : 1'b0;

    // -----------------------------------------------------------------------
    // Busy Indicator
    // -----------------------------------------------------------------------
    assign busy = (curr_state != STATE_IDLE);

endmodule

output.rtl/barrel_shifter_8bit.sv:
// rtl/barrel_shifter_8bit.sv
module barrel_shifter_8bit (
    input  logic [7:0] data_in,
    input  logic [2:0] shift_bits,
    input  logic       left_right,
    output logic [7:0] data_out
);

    // Combinational logic implementation for the 8-bit barrel shifter
    // Completes within one clock cycle as requested
    always_comb begin
        if (left_right) begin
            // Shift left: zeros fill LSB positions
            data_out = data_in << shift_bits;
        end else begin
            // Shift right: zeros fill MSB positions
            data_out = data_in >> shift_bits;
        end
    end

endmodule

output.rtl/bcd_counter.sv:
module bcd_counter (
    input  logic clk,
    input  logic rst,
    output logic [3:0] ms_hr,
    output logic [3:0] ls_hr,
    output logic [3:0] ms_min,
    output logic [3:0] ls_min,
    output logic [3:0] ms_sec,
    output logic [3:0] ls_sec
);
    logic [3:0] n_ls_sec, n_ms_sec;
    logic [3:0] n_ls_min, n_ms_min;
    logic [3:0] n_ls_hr,  n_ms_hr;

    // Combinational logic to compute next states
    always_comb begin
        // Default: hold current value
        n_ls_sec = ls_sec; n_ms_sec = ms_sec;
        n_ls_min = ls_min; n_ms_min = ms_min;
        n_ls_hr  = ls_hr;  n_ms_hr  = ms_hr;

        // Seconds logic
        if (ls_sec == 4'd9) begin
            n_ls_sec = 4'd0;
            if (ms_sec == 4'd5) begin
                n_ms_sec = 4'd0;
                // Carry to Minutes
                if (ls_min == 4'd9) begin
                    n_ls_min = 4'd0;
                    if (ms_min == 4'd5) begin
                        n_ms_min = 4'd0;
                        // Carry to Hours
                        if (ms_hr == 4'd2 && ls_hr == 4'd3) begin
                            n_ms_hr = 4'd0;
                            n_ls_hr = 4'd0;
                        end else if (ls_hr == 4'd9) begin
                            n_ls_hr = 4'd0;
                            n_ms_hr = ms_hr + 1'b1;
                        end else begin
                            n_ls_hr = ls_hr + 1'b1;
                        end
                    end else begin
                        n_ms_min = ms_min + 1'b1;
                    end
                end else begin
                    n_ls_min = ls_min + 1'b1;
                end
            end else begin
                n_ms_sec = ms_sec + 1'b1;
            end
        end else begin
            n_ls_sec = ls_sec + 1'b1;
        end
    end

    // Sequential logic to register outputs
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            ms_hr <= 4'd0;
            ls_hr <= 4'd0;
            ms_min <= 4'd0;
            ls_min <= 4'd0;
            ms_sec <= 4'd0;
            ls_sec <= 4'd0;
        end else begin
            ms_hr <= n_ms_hr;
            ls_hr <= n_ls_hr;
            ms_min <= n_ms_min;
            ls_min <= n_ls_min;
            ms_sec <= n_ms_sec;
            ls_sec <= n_ls_sec;
        end
    end
endmodule

output.rtl/bcd_to_excess_3.sv:
module bcd_to_excess_3 (
    input  logic [3:0] bcd,
    output logic [3:0] excess3,
    output logic       error
);

    always_comb begin
        if (bcd >= 10) begin
            excess3 = 4'b0000;
            error   = 1'b1;
        end else begin
            excess3 = bcd + 3;
            error   = 1'b0;
        end
    end

endmodule

